import urllib.request
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path: str) -> str:
        url = self.base_url + path
        max_retries = 3
        backoff_times = [0.5, 1.0, 2.0]

        for attempt in range(max_retries):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    status = response.status
                    body = response.read().decode('utf-8')

                    if status == 429:
                        if attempt < max_retries - 1:
                            time.sleep(backoff_times[attempt])
                            continue
                        else:
                            raise RateLimitError(f"Rate limited after {max_retries} attempts")
                    elif 500 <= status < 600:
                        # Server error: retry once after 1s
                        if attempt == 0:
                            time.sleep(1.0)
                            continue
                        else:
                            raise ServerError(f"Server error: {status}")
                    elif 400 <= status < 500:
                        if status == 429:
                            # handled above
                            pass
                        else:
                            raise ClientError(f"Client error: {status}")
                    else:
                        return body

            except urllib.error.HTTPError as e:
                status = e.code
                if status == 429:
                    if attempt < max_retries - 1:
                        time.sleep(backoff_times[attempt])
                        continue
                    else:
                        raise RateLimitError(f"Rate limited after {max_retries} attempts")
                elif 500 <= status < 600:
                    if attempt == 0:
                        time.sleep(1.0)
                        continue
                    else:
                        raise ServerError(f"Server error: {status}")
                elif 400 <= status < 500:
                    raise ClientError(f"Client error: {status}")
                else:
                    raise ClientError(f"Client error: {status}")

            except urllib.error.URLError:
                if attempt == 0:
                    time.sleep(1.0)
                    continue
                else:
                    raise ConnectionError(f"Connection error after retry")

        # Should not reach here, but just in case
        raise ConnectionError("Connection error after all retries")
